const Icon = ({ n, size = 18, color, style, className }) => (
  <svg viewBox="0 0 24 24" width={size} height={size} fill={color || "currentColor"} aria-hidden="true"
    className={className} style={{ flex: "none", display: "inline-block", ...style }}>
    <path d={ICON_PATHS[n]} />
  </svg>
);
const mk = (n) => (p) => <Icon n={n} size={p.size} color={p.color} style={p.style} className={p.className} />;
/* Names kept from the earlier build so the screen markup is unchanged. */
const ChevronDown = mk("keyboard_arrow_down"), ChevronUp = mk("keyboard_arrow_up"), ChevronRight = mk("chevron_right");
const Link2 = mk("link"), Copy = mk("content_copy"), MoreHorizontal = mk("more_horiz"), Search = mk("search"), Bell = mk("notifications");
const PanelLeft = mk("dock_to_right"), PanelRight = mk("dock_to_left"), Save = mk("save"), Send = mk("send"), X = mk("close");
const Maximize2 = mk("open_in_full"), ThumbsUp = mk("thumb_up"), ThumbsDown = mk("thumb_down"), Pencil = mk("edit"), RefreshCw = mk("refresh");
const FileText = mk("description"), Flag = mk("flag"), FlagTriangleRight = mk("flag"), AlertTriangle = mk("warning"), Check = mk("check");
const Clock = mk("schedule"), History = mk("history"), User = mk("person"), PatientDoc = mk("assignment_ind");
const CalendarDays = mk("calendar_month"), CalIcon = mk("calendar_today"), ShieldPlus = mk("health_and_safety"), ShieldCheck = mk("health_and_safety");
const Stethoscope = mk("stethoscope"), Hospital = mk("local_hospital"), Code2 = mk("code"), BriefcaseMedical = mk("medical_services");
const CalendarPlus = mk("calendar_add_on"), FileClock = mk("pending_actions"), ListChecks = mk("checklist"), Layers = mk("layers");
const Settings = mk("settings"), HelpCircle = mk("help"), Users = mk("supervisor_account"), ClipboardCheck = mk("fact_check");
const Eye = mk("visibility"), Archive = mk("archive"), CircleDollarSign = mk("request_quote"), Banknote = mk("payments");
const Upload = mk("drive_folder_upload"), PieChart = mk("pie_chart"), ExternalLink = mk("arrow_outward");
const MessageSquareOff = mk("comments_disabled"), Lightbulb = mk("lightbulb");
const Add = mk("add"), CheckCircle = mk("check_circle"), CancelSend = mk("cancel_schedule_send");
const MeetingRoom = mk("meeting_room"), Autorenew = mk("autorenew"), RateReview = mk("rate_review"), PlaylistRemove = mk("playlist_remove");
const CategoryIcon = mk("category"), CancelIcon = mk("cancel"), AttachFile = mk("attach_file"), SortIcon = mk("sort"), Tune = mk("tune");
const ArrowDown = mk("arrow_downward"), BellOff = mk("notifications_off"), Block = mk("block");
const FilterList = mk("filter_list"), Drag = mk("drag_indicator"), Minus = mk("remove"), CommentIcon = mk("comment"), ArrowFwd = mk("arrow_forward"), Widgets = mk("widgets"), DropDown = mk("arrow_drop_down");
const Info = mk("info"), Print = mk("print"), IdBadge = mk("badge"), UploadFile = mk("upload_file"), UnfoldMore = mk("unfold_more"), UnfoldLess = mk("unfold_less"), Keep = mk("keep");
