const BTN_TYPE = { primary: "primary", secondary: "secondary", tertiary: "tertiary", outline: "neutral", neutral: "neutral", ai: "neutral ai" };
const Btn = ({ v = "outline", size = "s", danger = false, loading = false, children, ...p }) => (
  <button {...p} className={`btn ${BTN_TYPE[v]} ${size}${danger ? " danger" : ""}${loading ? " loading" : ""}`} disabled={p.disabled || loading}>
    {loading ? <span className="spin" /> : children}
  </button>
);
const ICON_PX = { xs: 16, s: 18, m: 20, l: 20 };
const IBtn = ({ icon: I, type = "neutral", sz = "s", cls = "", size: _ignored, disabled, loading = false, onColor = false, badge = null, ...p }) => (
  <button {...p} className={`ibtn ${type} ${sz} ${cls}${loading ? " loading" : ""}${onColor ? " onColor" : ""}`} disabled={disabled || loading || cls.includes("disabled")}>
    {loading ? <span className="spin" /> : <I size={ICON_PX[sz]} strokeWidth={1.6} />}
    {badge && <span className={`abadge ${badge}`} />}
  </button>
);
/* items: [{ icon, label, onClick }]. Icon items render as icon buttons, labeled items as buttons. */
const BtnGroup = ({ style = "neutral", size = "s", items = [] }) => (
  <div className={`bgroup ${style} ${size}`} role="group">
    {items.flatMap((it, i) => {
      const node = it.icon
        ? <IBtn key={`b${i}`} icon={it.icon} sz={size} type={style === "neutral" ? "neutral" : "accentSubtle"} onClick={it.onClick} />
        : <Btn key={`b${i}`} v={style === "neutral" ? "neutral" : "tertiary"} size={size} onClick={it.onClick}>{it.label}</Btn>;
      return i ? [<i key={`d${i}`} className="bdiv" />, node] : [node];
    })}
  </div>
);
