/* Properties panel pieces */
/* "Why this action is suggested": clamped to 2 lines, with Show more / Show less when the text is longer */
function Why({ children }) {
  const ref = useRef(null);
  const [open, setOpen] = useState(false);
  const [over, setOver] = useState(false);
  useEffect(() => {
    const el = ref.current;
    if (!el) return;
    const check = () => { if (!open) setOver(el.scrollHeight > el.clientHeight + 1); };
    check();
    const ro = typeof ResizeObserver !== "undefined" ? new ResizeObserver(check) : null;
    ro && ro.observe(el);
    return () => ro && ro.disconnect();
  }, [open]);
  return (
    <>
      <p ref={ref} className={`sact-why${open ? "" : " clamp"}`}>{children}</p>
      {(over || open) && (
        <button className="sact-link more why-more" onClick={() => setOpen((o) => !o)} aria-expanded={open}>
          {open ? "Show less" : "Show more"} {open ? <ChevronUp size={16} /> : <ChevronDown size={16} />}
        </button>
      )}
    </>
  );
}
