const TODAY = new Date(2026, 10, 19);
const fmtDate = (d) => d.toLocaleDateString("en-US", { weekday: "short", month: "short", day: "numeric" });
const addDays = (n) => { const d = new Date(TODAY); d.setDate(d.getDate() + n); return d; };
const parseISO = (v) => { const [y, m, d] = v.split("-").map(Number); return new Date(y, m - 1, d); };
const PRESETS = [{ id: "2d", label: "2 days", days: 2 }, { id: "1w", label: "1 week", days: 7 }, { id: "2w", label: "2 weeks", days: 14 }];
const untilOf = (x) => x.expiry === "custom" ? (x.custom ? fmtDate(parseISO(x.custom)) : null) : fmtDate(addDays(PRESETS.find((p) => p.id === x.expiry).days));
const REASONS = [
  { id: "addendum", kind: "global", label: "Request addendum", desc: "Ask the provider to review the note and sign an addendum.", needsContext: true },
  { id: "reprocessing", kind: "global", label: "Claim Reprocessing", desc: "Send the claim back through reprocessing." },
  { id: "updated", kind: "global", label: "Updated in EHR", desc: "Wait for the claim to be updated in the EHR." },
  { id: "chart", kind: "global", label: "Awaiting chart note update in EHR", desc: "Wait for a change to the chart note in the EHR." },
];
const ERA_DAYS = [...Array.from({ length: 55 }, (_, i) => 30 + i), 86, 87, 88, 89, 90, 91, 92, 93, 94, 95, 97, 98, 99, 100, 101, 103, 104, 105, 106, 107, 109, 110, 113, 114, 118, 119, 122, 124, 126, 127, 130, 132, 133, 134, 135, 136, 137, 140, 141, 142, 146, 148, 149, 152, 155, 156, 157, 164, 165, 166, 167, 168, 169, 173];
const CUSTOM_LABELS = [
  "test reason for site 2", "Waiting 30 days to resubmit", "Claim Recon Test",
  "Claim has been resubmitted to insurance company for processing. No PR should be generated at this time.",
  "Sent Records", "Claims were resubmitted to Cigna as there was an credentialing issue", "Rebecca Fisher Credentialing Defer",
  "Waiting on rule update", "Legal Claims", "Specialized Claims Team Support", "Awaiting payer response", "Athelas Reviewing",
  ...ERA_DAYS.map((n) => `Expected time to ERA for this payer is up to ${n} days`),
  "ERA timing for this payer is variable and may exceed 55 days", "AK Medicaid New Combo Enrollment", "Awaiting EOB processing",
  "Site responsibility to process through Wellmark portal.", "Ins called site and they are reprocessing claims. Do not collect PR.",
  "awaiting correct member ID", "Rebecca Fisher License AK Medicaid", "Credit issued to site...will be w/o",
  "Appealed and awaiting payers response.", "Ins sending back for reprocessing. Per site do not collect as of now.",
  "Waiting update from eCW", "Waiting on provider credentialing", "West Boca facility issue, waiting for confirmation.",
  "Pending access to Ashlink Portal", "Site waiting for credentialing. Nothing to do here.", "Awaiting response from site",
  "Fixed and Resubmitted", "Pending review of Northern California Medicare Submissions", "Duplicate Claims", "Sent Back to Therapist",
  "CMS Access CO132 denial", "Pending Attorney Update", "dispute on Availity", "Awaiting Mallory Brown's Credentialing.",
  "Awaiting Champva portal approval", "pending review of appeal",
];
/* Assumption for the demo: these site reasons were created by the person using the prototype, so they can be edited and deleted. */
const MINE = new Set(["test reason for site 2", "Claim Recon Test", "Rebecca Fisher Credentialing Defer", "Awaiting Mallory Brown's Credentialing.", "awaiting correct member ID", "pending review of appeal"]);
const CUSTOM = CUSTOM_LABELS.map((label, i) => ({ id: `c${i}`, kind: "custom", label, own: MINE.has(label) }));
const ALL_REASONS = [...REASONS, ...CUSTOM];
const AI_TEXT = "Please review the diagnoses on this encounter. Wellmark denied all three lines (97110, 97112, and 97530) under CO-16 with remark M76 for a missing or invalid diagnosis. R42 conflicts with H81.22 (Excludes1). If R42 should be removed, please sign an addendum so we can resubmit.";
const DR_INIT = { open: false, reason: null, tab: "all", context: "", source: null, expiry: "2d", custom: "", query: "", thinking: false };
const TABS = [["all", "All"], ["global", "Global"], ["custom", "Custom"]];

function DeferDrawer({ st, set, custom, onAddReason, onRenameReason, onDeleteReason, onClose, onConfirm }) {
  const ref = useRef(null);
  const bodyRef = useRef(null);
  const fRef = useRef(null);
  const minH = useRef(0);
  const [fh, setFh] = useState(null);
  const [adding, setAdding] = useState(false);
  const [draft, setDraft] = useState("");
  const [note, setNote] = useState("");
  const [editId, setEditId] = useState(null);
  const [editDraft, setEditDraft] = useState("");
  const [editError, setEditError] = useState("");
  const [delId, setDelId] = useState(null);
  useEffect(() => { ref.current && ref.current.focus(); }, []);
  useEffect(() => {
    const h = (e) => { if (e.key === "Escape") onClose(); };
    window.addEventListener("keydown", h);
    return () => window.removeEventListener("keydown", h);
  });
  const allReasons = [...REASONS, ...custom];
  const reason = allReasons.find((r) => r.id === st.reason);
  const until = untilOf(st);
  const q = st.query.trim().toLowerCase();
  const found = allReasons.filter((r) => !q || r.label.toLowerCase().includes(q));
  const count = { all: found.length, global: found.filter((r) => r.kind === "global").length, custom: found.filter((r) => r.kind === "custom").length };
  const list = st.tab === "all" ? found : found.filter((r) => r.kind === st.tab);
  const valid = !!reason && !!until && (!reason.needsContext || !!st.context.trim());
  /* The bottom container can be dragged up to give the context box more room. Its natural height is the floor. */
  const canSize = !!reason && !!reason.needsContext;
  useEffect(() => { if (!canSize) setFh(null); }, [canSize]);
  const maxFor = () => Math.max((ref.current ? ref.current.offsetHeight : 0) * 0.6, minH.current + 240);
  const clampH = (h) => Math.min(maxFor(), Math.max(minH.current, h));
  const startDrag = (e) => {
    e.preventDefault();
    const el = fRef.current, startY = e.clientY, startH = el.offsetHeight;
    if (fh === null) minH.current = startH;
    const move = (ev) => setFh(clampH(startH + (startY - ev.clientY)));
    const up = () => { window.removeEventListener("pointermove", move); window.removeEventListener("pointerup", up); };
    window.addEventListener("pointermove", move);
    window.addEventListener("pointerup", up);
  };
  const nudge = (dy) => {
    const el = fRef.current;
    if (fh === null) minH.current = el.offsetHeight;
    setFh(clampH((fh === null ? el.offsetHeight : fh) + dy));
  };
  const startEdit = (r) => { setEditId(r.id); setEditDraft(r.label); setEditError(""); setDelId(null); };
  const cancelEdit = () => { setEditId(null); setEditError(""); };
  const saveEdit = () => {
    const res = onRenameReason(editId, editDraft);
    if (res === "duplicate") return setEditError("That name is already used.");
    if (res === "empty") return setEditError("Give the reason a name.");
    cancelEdit();
  };
  const submitNew = () => {
    const res = onAddReason(draft);
    if (!res) return;
    set((s) => ({ ...s, reason: res.id, tab: s.tab === "global" ? "custom" : s.tab, query: "" }));
    setNote(res.existed ? "That reason already exists, so it is selected." : "");
    setAdding(false);
    setDraft("");
    setTimeout(() => {
      const b = bodyRef.current, el = b && b.querySelector('[aria-checked="true"]');
      if (b && el) b.scrollTop = Math.max(0, el.getBoundingClientRect().top - b.getBoundingClientRect().top + b.scrollTop - 48);
    }, 60);
  };
  const suggest = () => {
    set((s) => ({ ...s, thinking: true }));
    setTimeout(() => set((s) => ({ ...s, thinking: false, context: AI_TEXT, source: "ai" })), 700);
  };
  /* Reasons you created can be renamed or deleted on the same line. Reasons that came with the site are read-only. */
  const reasonRow = (r) => {
    if (r.own && editId === r.id) return (
      <div key={r.id} className="rrow editing">
        <div className="ropt editrow">
          <input className="einput" autoFocus aria-label="Reason name" value={editDraft} onChange={(e) => { setEditDraft(e.target.value); setEditError(""); }}
            onKeyDown={(e) => { if (e.key === "Enter") saveEdit(); if (e.key === "Escape") { e.stopPropagation(); cancelEdit(); } }} />
          <IBtn icon={Check} sz="xs" type="accentSubtle" aria-label="Save changes" onClick={saveEdit} />
          <IBtn icon={X} sz="xs" aria-label="Cancel editing" onClick={cancelEdit} />
        </div>
        {editError && <div className="rerr" role="alert">{editError}</div>}
      </div>
    );
    if (r.own && delId === r.id) return (
      <div key={r.id} className="rrow">
        <div className="ropt confirm" role="alertdialog" aria-label={`Delete ${r.label}`}>
          <span className="ropt-t" style={{ flex: 1, minWidth: 0 }}>Delete "{r.label}"?</span>
          <Btn v="tertiary" danger onClick={() => { onDeleteReason(r.id); setDelId(null); }}>Delete</Btn>
          <Btn v="tertiary" onClick={() => setDelId(null)}>Cancel</Btn>
        </div>
      </div>
    );
    return (
      <div key={r.id} className={`rrow${r.own ? " own" : ""}`}>
        <button role="radio" aria-checked={st.reason === r.id} className={`ropt${st.reason === r.id ? " on" : ""}${r.desc ? "" : " compact"}`} onClick={() => set((s) => ({ ...s, reason: r.id }))}>
          <span className={`radio ${st.reason === r.id ? "on" : ""}`} />
          <span><span className="ropt-t">{r.label}</span>{r.desc && <span className="ropt-d">{r.desc}</span>}</span>
        </button>
        {r.own && (
          <div className="ract">
            <IBtn icon={Pencil} sz="xs" aria-label={`Edit ${r.label}`} onClick={() => startEdit(r)} />
            <IBtn icon={Trash} sz="xs" type="destructiveSubtle" aria-label={`Delete ${r.label}`} onClick={() => { setDelId(r.id); cancelEdit(); }} />
          </div>
        )}
      </div>
    );
  };
  return (
    <div className="scrim" onMouseDown={onClose}>
      <aside className="drawer" role="dialog" aria-modal="true" aria-label="Defer claim" tabIndex={-1} ref={ref} onMouseDown={(e) => e.stopPropagation()}>
        <div className="dr-h">
          <div>
            <div className="dr-t">Defer claim</div>
            <div className="dr-s">Claim 25223806, Michelle Kruse</div>
          </div>
          <IBtn icon={X} aria-label="Close" onClick={onClose} />
        </div>

        <div className="dr-top">
          <div className="dr-search">
            <div className="field" style={{ flex: 1 }}><Search size={16} /><input className="fin2" placeholder="Search reasons" aria-label="Search reasons" value={st.query} onChange={(e) => set((s) => ({ ...s, query: e.target.value }))} /></div>
            <Btn v="neutral" aria-label="Add a custom reason" aria-expanded={adding} onClick={() => { setAdding((a) => !a); setNote(""); }}><Add /> Add</Btn>
          </div>
          {adding && (
            <div className="dr-search">
              <div className="field" style={{ flex: 1 }}>
                <input className="fin2" autoFocus placeholder="Name the new reason" aria-label="New reason name" value={draft}
                  onChange={(e) => setDraft(e.target.value)}
                  onKeyDown={(e) => { if (e.key === "Enter") submitNew(); if (e.key === "Escape") { e.stopPropagation(); setAdding(false); setDraft(""); } }} />
              </div>
              <Btn v="primary" disabled={!draft.trim()} onClick={submitNew}>Add reason</Btn>
              <Btn v="tertiary" onClick={() => { setAdding(false); setDraft(""); }}>Cancel</Btn>
            </div>
          )}
          {note && <div className="dr-hint" style={{ margin: 0 }}>{note}</div>}
          <div className="dr-tabs" role="tablist" aria-label="Reason type">
            {TABS.map(([id, label]) => (
              <button key={id} role="tab" aria-selected={st.tab === id} className={`dr-tab${st.tab === id ? " on" : ""}`} onClick={() => set((s) => ({ ...s, tab: id }))}>
                {label} ({count[id]})
              </button>
            ))}
          </div>
        </div>

        <div className="dr-b" role="radiogroup" aria-label="Deferral reason" ref={bodyRef}>
          {st.tab === "all"
            ? [["Global", found.filter((r) => r.kind === "global")], ["Custom", found.filter((r) => r.kind === "custom")]]
                .filter(([, items]) => items.length)
                .map(([title, items]) => (
                  <div key={title} role="group" aria-label={title}>
                    <div className="dr-grp">{title}</div>
                    {items.map(reasonRow)}
                  </div>
                ))
            : list.map(reasonRow)}
          {!list.length && <div className="rempty">No reasons match "{st.query}" in this tab.</div>}
        </div>

        <div className={`dr-f${fh !== null ? " sized" : ""}`} ref={fRef} style={fh !== null ? { height: fh, maxHeight: "none" } : undefined}>
          {canSize && (
            <div className="dr-grab" role="separator" aria-orientation="horizontal" aria-label="Drag up to make the context box taller" tabIndex={0}
              onPointerDown={startDrag} onDoubleClick={() => setFh(null)}
              onKeyDown={(e) => { if (e.key === "ArrowUp") { e.preventDefault(); nudge(24); } if (e.key === "ArrowDown") { e.preventDefault(); nudge(-24); } }}>
              <span className="dr-grab-bar" />
            </div>
          )}
          <div className="dr-fc">
            
            {reason && reason.needsContext && (
              <div className="ctx">
                <div className="dr-row">
                  <div className="flabel" style={{ margin: 0 }}>Context for the provider</div>
                  <Btn v="tertiary" loading={st.thinking} onClick={suggest}><Sparkles /> Suggest with AI</Btn>
                </div>
                <div className="dr-to">To <span className="vchip">Logan Albaugh</span></div>
                <textarea className="ftext" rows={3} value={st.context} aria-label="Context for the provider" placeholder="Tell the provider what to review or change"
                  onChange={(e) => set((s) => ({ ...s, context: e.target.value, source: s.source === "ai" ? "edited" : s.source }))} />
                {st.source ? <div className="dr-hint">{st.source === "ai" ? "Suggested by AI. Edit it before you send." : "Edited from the AI suggestion."}</div>
                  : !st.context.trim() && <div className="dr-hint">Required. The provider sees this above the note.</div>}
              </div>
            )}

            <div>
              <div className="flabel">Defer until</div>
              <div className="xrow">
                {PRESETS.map((p) => (
                  <button key={p.id} className="xchip" aria-pressed={st.expiry === p.id} onClick={() => set((s) => ({ ...s, expiry: p.id }))}>
                    <b>{p.label}</b><span>{fmtDate(addDays(p.days))}</span>
                  </button>
                ))}
                <button className="xchip" aria-pressed={st.expiry === "custom"} onClick={() => set((s) => ({ ...s, expiry: "custom" }))}>
                  <b>Pick a date</b>{st.expiry === "custom" && until && <span>{until}</span>}
                </button>
              </div>
              {st.expiry === "custom" && (
                <div className="field" style={{ marginTop: 8, width: 200 }}>
                  <CalIcon size={16} />
                  <input className="fin2" type="date" aria-label="Defer until date" min="2026-11-20" value={st.custom} onChange={(e) => set((s) => ({ ...s, custom: e.target.value }))} />
                </div>
              )}
            </div>

                      </div>
          <div className="dr-btns">
            <Btn v="neutral" size="m" onClick={onClose}>Cancel</Btn>
            <Btn v="primary" size="m" disabled={!valid} onClick={onConfirm}>Defer claim</Btn>
          </div>
        </div>
      </aside>
    </div>
  );
}

